-- =============================================================================
-- 004 — Data real de cadastro do cliente
--
-- POR QUÊ: `created_at` guarda quando a linha entrou neste banco, ou seja, o
-- dia da migração — os 1.825 clientes ficaram todos em agosto de 2026. O
-- sistema antigo tem a data verdadeira em cada ficha, e sem ela o painel não
-- consegue dizer "clientes novos no mês" sem mentir.
--
-- Esta migração cria a coluna e já preenche os 1.825 a partir do que foi
-- extraído do legado. Cliente cadastrado daqui para frente recebe a data de
-- hoje pelo próprio painel.
--
-- Rode inteiro. Está em transação.
-- =============================================================================

begin;

alter table public.clientes
  add column if not exists cadastrado_em date;

comment on column public.clientes.cadastrado_em is
  'Data em que o cliente se cadastrou, vinda do sistema antigo. Diferente de created_at, que é quando a linha entrou neste banco.';

